INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000001, 190801, 1, 1, 0.0, 2, -416.5, "2030/01/01 14:59:59", 62, "2025/01/31 12:00:00", 1, 3.414, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000002, 190801, 1, 2, 0.0, 2, -416.5, "2030/01/01 14:59:59", 62, "2025/01/31 12:00:00", 1, 3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000003, 190801, 1, 3, 0.0, 2, -416.5, "2030/01/01 14:59:59", 63, "2025/01/31 12:00:00", 1, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000004, 190801, 2, 4, 0.0, 2, -416.5, "2030/01/01 14:59:59", 63, "2025/01/31 12:00:00", 1, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000005, 190801, 2, 5, 0.0, 1, -363.0, "2030/01/01 14:59:59", 64, "2025/01/31 12:00:00", 1, 2.12, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000006, 190801, 1, 6, 0.0, 2, -363.0, "2030/01/01 14:59:59", 64, "2025/01/31 12:00:00", 1, 1.68, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1000007, 190801, 2, 7, 0.0, 1, -363.0, "2030/01/01 14:59:59", 64, "2025/01/31 12:00:00", 1, 2.33, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020101, 133701, 3, 101, -6.0, 7, -285.0, "2030/01/01 14:59:59", 61, "2025/01/31 12:00:00", 10201, 5.18, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020102, 133901, 1, 201, -2.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/01/31 12:00:00", 10201, 8.77, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", "クリスティーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020103, 133801, 6, 301, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2025/01/31 12:00:00", 10201, 15.5, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", "ネネカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020201, 134301, 2, 101, 0.0, 5, -285.0, "2030/01/01 14:59:59", 61, "2025/02/28 12:00:00", 10202, 9.061, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", "ランファ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020202, 134401, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/02/28 12:00:00", 10202, 7.699, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", "チカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020301, 134601, 1, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/03/31 12:00:00", 10203, 8.595, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", "アオイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020302, 134501, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/03/31 12:00:00", 10203, 7.758, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", "クローチェ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020401, 132302, 2, 101, 0.0, 6, -285.0, "2030/01/01 14:59:59", 61, "2025/04/30 12:00:00", 10204, 7.0, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020402, 132402, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/04/30 12:00:00", 10204, 7.904, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", "イロハ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020403, 132502, 4, 301, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/04/30 12:00:00", 10204, 8.487, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", "ソノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020502, 134901, 1, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/05/31 12:00:00", 10205, 8.763, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", "カノン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020503, 134801, 1, 201, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2025/05/31 12:00:00", 10205, 6.417, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", "ツムギ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020601, 135001, 3, 101, 0.0, 7, -285.0, "2030/01/01 14:59:59", 61, "2025/06/30 12:00:00", 10206, 10.335, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", "エリス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020602, 135101, 2, 201, 0.0, 4, -285.0, "2030/01/01 14:59:59", 61, "2025/06/30 12:00:00", 10206, 6.281, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", "シェフィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020603, 135201, 1, 301, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/06/30 12:00:00", 10206, 12.244, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020701, 135301, 2, 101, 0.0, 8, -285.0, "2030/01/01 14:59:59", 61, "2025/07/31 12:00:00", 10207, 6.339, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020702, 135401, 7, 201, 0.0, 9, -285.0, "2030/01/01 14:59:59", 61, "2025/07/31 12:00:00", 10207, 8.184, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", "アネモネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020801, 129101, 9, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/08/31 12:00:00", 10208, 3.906, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", "アイラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020802, 129201, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/08/31 12:00:00", 10208, 14.465, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", "シナツ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020803, 100101, 4, 301, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2025/08/31 12:00:00", 10208, 8.662, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", "ヒヨリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020804, 100301, 1, 401, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2025/08/31 12:00:00", 10208, 10.915, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", "レイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020901, 135802, 1, 101, 0.0, 7, -285.0, "2030/01/01 14:59:59", 61, "2025/09/30 12:00:00", 10209, 6.042, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", "ユキノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020902, 135903, 4, 201, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2025/09/30 12:00:00", 10209, 9.402, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", "サツキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1020903, 136902, 8, 301, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2025/09/30 12:00:00", 10209, 8.16, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021001, 137401, 3, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/10/31 12:00:00", 10210, 5.0, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", "カスミ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021002, 136001, 4, 201, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2025/10/31 12:00:00", 10210, 8.12, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", "アラクネ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021003, 136202, 4, 301, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/10/31 12:00:00", 10210, 6.386, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", "ナーナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021101, 136402, 3, 101, 0.0, 4, -285.0, "2030/01/01 14:59:59", 61, "2025/11/30 12:00:00", 10211, 7.438, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", "ユイ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021102, 136302, 1, 201, 0.0, 5, -285.0, "2030/01/01 14:59:59", 61, "2025/11/30 12:00:00", 10211, 8.35, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", "ミソラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021201, 136501, 1, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/12/31 12:00:00", 10212, 5.0, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", "シズル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021202, 137902, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/12/31 12:00:00", 10212, 5.25, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", "リノ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021203, 106801, 1, 301, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2025/12/31 12:00:00", 10212, 7.5, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", "ラビリスタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021301, 126501, 1, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/01/31 12:00:00", 10213, 8.204, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021302, 129701, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/01/31 12:00:00", 10213, 7.176, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021303, 133101, 1, 301, 0.0, 5, -285.0, "2030/01/01 14:59:59", 61, "2026/01/31 12:00:00", 10213, 8.602, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021304, 138101, 1, 102, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/02/06 12:00:00", 10213, 10.14, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", "ライラエル");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021305, 138201, 1, 202, 0.0, 7, -285.0, "2030/01/01 14:59:59", 61, "2026/02/06 12:00:00", 10213, 10.152, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", "ネフィ＝ネラ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021306, 138001, 4, 302, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/02/06 12:00:00", 10213, 9.688, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", "ヴァイオレット");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021307, 138301, 2, 401, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/02/12 12:00:00", 10213, 5.928, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", "ペコリーヌ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021401, 138702, 4, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/02/28 12:00:00", 10214, 9.19, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", "ワカナ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021402, 138802, 1, 201, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/02/28 12:00:00", 10214, 8.724, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", "シオリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021501, 138902, 4, 101, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/03/31 12:00:00", 10215, 7.758, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", "グレイス");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021502, 139002, 6, 201, 0.0, 4, -285.0, "2030/01/01 14:59:59", 61, "2026/03/31 12:00:00", 10215, 6.375, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", "キョウカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021503, 136902, 6, 301, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/03/31 12:00:00", 10215, 6.173, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", "ルルィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021601, 139202, 6, 101, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/04/30 12:00:00", 10216, 4.202, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", "ミホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021602, 139302, 6, 201, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/04/30 12:00:00", 10216, 2.842, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", "マホ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021603, 139402, 4, 301, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/04/30 12:00:00", 10216, 4.598, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", "エリカ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021701, 125802, 4, 101, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 6.533, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021702, 126102, 3, 301, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 5.0, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021703, 126002, 3, 201, 0.0, 4, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 5.214, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021704, 139501, 1, 102, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 8.781, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", "リリ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021705, 139601, 2, 202, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 6.529, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", "クリア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021706, 139701, 3, 302, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/05/31 12:00:00", 10217, 3.195, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", "プレシア");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021801, 139902, 2, 101, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/06/30 12:00:00", 10218, 12.43, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", "ルイズマリー");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021802, 140001, 2, 201, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/06/30 12:00:00", 10218, 6.35, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", "クレジッタ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021901, 140102, 1, 101, 0.0, 5, -285.0, "2030/01/01 14:59:59", 61, "2026/07/31 12:00:00", 10219, 10.23, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", "フブキ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1021902, 140201, 1, 201, 0.0, 2, -285.0, "2030/01/01 14:59:59", 61, "2026/07/31 12:00:00", 10219, 5.584, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", "ヴァンピィ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1022001, 126401, 6, 201, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/08/31 12:00:00", 10220, 2.8, "あっちもこっちも、\nエマージェンシーですっ！\nみんなのピンチを助けるために\n行きましょうっ、ナイトさんっ！", "クローチェ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1022002, 127802, 4, 101, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/08/31 12:00:00", 10220, 8.9, "みんながあたしを許してくれても…\nあたしは、あたしを許せない\nそれでも…この世界が危ないなら\n迷ってなんか、いられない", "ヴルム");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1022003, 140602, 2, 202, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/08/31 12:00:00", 10220, 4.49, "クローチェ、サブマリンモードっ\n換装完了ですっ♪\nどんな荒波も、ナイトさんとなら\n越えちゃいますからっ！", "クローチェ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1022004, 140501, 1, 102, 0.0, 3, -285.0, "2030/01/01 14:59:59", 61, "2026/08/31 12:00:00", 10220, 9.42, "偽物でも、創り物でもいい\nあたしの中にある気持ちは、\nあたしの本物だから\n今度こそ、この力で守ってみせる", "ヴルム");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1022005, 140402, 4, 301, 0.0, 1, -285.0, "2030/01/01 14:59:59", 61, "2026/08/31 12:00:00", 10220, 7.0, "世界と向き合うなんてこと…\n私には、わからない\nそれでも、受けた借りは\nちゃんと返さないとね", "リーザ");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000001, 190805, 1, 1, 0.0, 2, -416.5, "2030/01/01 14:59:59", 62, "2026/04/10 12:00:00", 2, 3.414, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000002, 190805, 1, 2, 0.0, 2, -416.5, "2030/01/01 14:59:59", 62, "2026/04/10 12:00:00", 2, 3.099, "ミッションをクリアして、\n報酬をゲットしましょう！", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000003, 190805, 1, 3, 0.0, 2, -416.5, "2030/01/01 14:59:59", 63, "2026/04/10 12:00:00", 2, 2.801, "受け取ることができる\n報酬があるようです\n確認してみてください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000004, 190805, 2, 4, 0.0, 2, -416.5, "2030/01/01 14:59:59", 63, "2026/04/10 12:00:00", 2, 0.0, "報酬がもらえますよ！\nチェックしてみてください", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000005, 190805, 2, 5, 0.0, 1, -363.0, "2030/01/01 14:59:59", 64, "2026/04/10 12:00:00", 2, 2.12, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000006, 190805, 1, 6, 0.0, 2, -363.0, "2030/01/01 14:59:59", 64, "2026/04/10 12:00:00", 2, 1.68, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", "カリン");
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2000007, 190805, 2, 7, 0.0, 1, -363.0, "2030/01/01 14:59:59", 64, "2026/04/10 12:00:00", 2, 2.33, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", "カリン");
